package com.nigson.experience.files;

import com.nigson.experience.careers.*;import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.assertj.core.api.Assertions.*;

class CareerPersistenceTest {
 private JdbcTemplate jdbc;private CareerService service;private CareerUploadSessionService files;private CareerSecrets secrets;private UUID opportunity;private final Clock clock=Clock.systemUTC();private final Map<UUID,String> uploadTokens=new HashMap<>();
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"career PostgreSQL scenarios run through scripts/careers/verify.py");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();var store=new PlatformStore(jdbc,manager,clock,metrics);var audit=new AuditWriter(jdbc,clock,metrics);byte[] aes=new byte[32],hmac=new byte[32];Arrays.fill(aes,(byte)9);Arrays.fill(hmac,(byte)7);secrets=new CareerSecrets(1,hmac,"test",Map.of("test",aes));CareerService.AntiSpamVerifier spam=(token,key)->"synthetic-anti-spam-token".equals(token);service=new CareerService(jdbc,store,audit,secrets,manager,clock,30,"SYNTHETIC_POLICY_NOT_APPROVED","synthetic-career-sheet-group",Set.of("portfolio"),spam);files=new CareerUploadSessionService(jdbc,store,audit,secrets,spam,clock,30,"SYNTHETIC_POLICY_NOT_APPROVED","synthetic-career-sheet-group");opportunity=UUID.randomUUID();jdbc.update("INSERT INTO experience.career_opportunity(id,created_by,updated_by,title,slug,kind,description,fields_schema,state) VALUES (?,'test','test','Engineer',?,'JOB','Details',?::jsonb,'PUBLISHED')",opportunity,"career-test-"+UUID.randomUUID().toString().substring(0,8),"{\"schemaVersion\":1,\"fields\":[{\"key\":\"portfolio\",\"type\":\"TEXT\",\"required\":true,\"maximumLength\":100},{\"key\":\"secret\",\"type\":\"TEXT\",\"required\":false,\"maximumLength\":100}]}");}
 private String capabilityHash(String token){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(token.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private UUID file(String scan){UUID session=EventCodec.uuid7(clock.instant()),file=EventCodec.uuid7(clock.instant());String token=UUID.randomUUID()+"."+UUID.randomUUID();String hash=capabilityHash(token);jdbc.update("INSERT INTO experience.upload_session(id,created_by,updated_by,token_hash,purpose,expires_at,maximum_bytes) VALUES (?,'test','test',?,'CAREER_CV',?,5242880)",session,hash,Timestamp(clock.instant().plusSeconds(1800)));jdbc.update("INSERT INTO experience.file_asset(id,created_by,updated_by,object_key,purpose,mime_type,byte_size,checksum_sha256,classification,scan_status,upload_session_id) VALUES (?,'test','test',?,'CAREER_CV','application/pdf',200,?,'PRIVATE',?,?)",file,"career-test/"+file,hash,scan,session);uploadTokens.put(file,token);return file;}
 private CareerValues.Submission submission(UUID file){return new CareerValues.Submission("Applicant One","Applicant@example.invalid",EventCodec.JSON.readTree("{\"portfolio\":\"https://portfolio.example.invalid\",\"secret\":\"private\"}"),file,"SYNTHETIC_POLICY_NOT_APPROVED","synthetic-anti-spam-token");}
 private PrivateWorkload.Proof proof(String api,ActorAssertion.Actor actor){var r=PrivateWorkload.ROUTES.stream().filter(v->v.api().equals(api)).findFirst().orElseThrow();return new PrivateWorkload.Proof(r.client(),"synthetic-workload",r,actor);}
 private static java.sql.Timestamp Timestamp(Instant value){return java.sql.Timestamp.from(value);}
 @Test void uploadSessionIsPurposeScopedAntiAbuseCheckedBoundedAndReplayableWithoutPlaintextPersistence(){long before=jdbc.queryForObject("SELECT count(*) FROM experience.upload_session",Long.class);String key=UUID.randomUUID().toString();var first=files.create("synthetic-anti-spam-token",key,UUID.randomUUID());assertThat(first.uploadToken()).hasSize(43).matches("[A-Za-z0-9_-]{43}");assertThat(first.maximumBytes()).isEqualTo(5L*1024*1024);assertThat(first.expiresAt()).isAfter(clock.instant().plusSeconds(1790)).isBefore(clock.instant().plusSeconds(1801));assertThat(files.create("synthetic-anti-spam-token",key,UUID.randomUUID())).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.upload_session",Long.class)).isEqualTo(before+1);var row=jdbc.queryForMap("SELECT owner_party_id,token_hash,purpose,expires_at,maximum_bytes,claimed_application_id FROM experience.upload_session WHERE token_hash=?",capabilityHash(first.uploadToken()));assertThat(row.get("owner_party_id")).isNull();assertThat(row.get("purpose")).isEqualTo("CAREER_CV");assertThat(row.get("maximum_bytes")).isEqualTo(5L*1024*1024);assertThat(row.get("claimed_application_id")).isNull();assertThat(((java.sql.Timestamp)row.get("expires_at")).toInstant()).isEqualTo(first.expiresAt());String storedResponse=jdbc.queryForObject("SELECT response_body::text FROM experience.idempotency_record WHERE principal_key='public:career' AND operation='API-157' AND request_key=?",String.class,key);assertThat(storedResponse).doesNotContain(first.uploadToken()).contains("protectedToken");assertThatThrownBy(()->files.create("rejected-anti-spam-token",UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.FILES_RULE_VIOLATION);assertThatThrownBy(()->files.create("different-anti-spam-token",key,UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.upload_session",Long.class)).isEqualTo(before+1);}
 @Test void quarantinedOrClaimedCvNeverCreatesAnApplicationAndCleanCvIsClaimedExactlyOnce(){UUID quarantined=file("QUARANTINED");assertThatThrownBy(()->service.submit(opportunity,submission(quarantined),uploadTokens.get(quarantined),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.career_application WHERE opportunity_id=?",Long.class,opportunity)).isZero();assertThat(jdbc.queryForObject("SELECT claimed_application_id FROM experience.upload_session WHERE id=(SELECT upload_session_id FROM experience.file_asset WHERE id=?)",UUID.class,quarantined)).isNull();UUID clean=file("CLEAN");String key=UUID.randomUUID().toString();assertThatThrownBy(()->service.submit(opportunity,submission(clean),"wrong-capability",key,UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.CAREERS_RULE_VIOLATION);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.career_application WHERE opportunity_id=?",Long.class,opportunity)).isZero();var first=service.submit(opportunity,submission(clean),uploadTokens.get(clean),key,UUID.randomUUID());var replay=service.submit(opportunity,submission(clean),uploadTokens.get(clean),key,UUID.randomUUID());assertThat(replay).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.career_application WHERE id=?",Long.class,first.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT linked_resource_id FROM experience.file_asset WHERE id=?",UUID.class,clean)).isEqualTo(first.id());assertThat(jdbc.queryForObject("SELECT claimed_application_id FROM experience.upload_session WHERE id=(SELECT upload_session_id FROM experience.file_asset WHERE id=?)",UUID.class,clean)).isEqualTo(first.id());byte[] ciphertext=jdbc.queryForObject("SELECT email_ciphertext FROM experience.career_application WHERE id=?",byte[].class,first.id());assertThat(new String(ciphertext,java.nio.charset.StandardCharsets.US_ASCII)).doesNotContain("Applicant@example.invalid");assertThat(secrets.decrypt(first.id(),ciphertext)).isEqualTo("applicant@example.invalid");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='career.application.created.v1'",Long.class,first.id())).isEqualTo(1);}
 @Test void sheetContextRetryIsStableAllowlistedAndNeverReturnsFileIdentifier(){UUID file=file("CLEAN");var created=service.submit(opportunity,submission(file),uploadTokens.get(file),UUID.randomUUID().toString(),UUID.randomUUID());var integration=proof("API-128",null);var first=service.sheet(integration,created.id(),UUID.randomUUID());var retry=service.sheet(integration,created.id(),UUID.randomUUID());assertThat(first.applicationId()).isEqualTo(retry.applicationId());assertThat(first.approvedAnswers().propertyNames()).containsExactly("portfolio");assertThat(first.approvedAnswers().toString()).doesNotContain("secret","private",file.toString());assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='career.application.created.v1'",Long.class,created.id())).isEqualTo(1);}
 @Test void transitionRequiresExactStaffScopeAndCurrentVersion(){UUID created=service.submit(opportunity,submission(null),null,UUID.randomUUID().toString(),UUID.randomUUID()).id();UUID party=UUID.randomUUID();var actor=new ActorAssertion.Actor(party,"http://synthetic.invalid","staff-test",null,Set.of("SALES"),Set.of("careers.manage_WITH_SIGNED_ACTOR"),null);var manage=proof("API-107",actor);assertThatThrownBy(()->service.transition(manage,created,new CareerValues.Transition("REVIEWED","Review started"),1,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.VERSION_MISMATCH);var changed=service.transition(manage,created,new CareerValues.Transition("REVIEWED","Review started"),0,UUID.randomUUID().toString(),UUID.randomUUID());assertThat(changed.version()).isEqualTo(1);var shortlisted=service.transition(manage,created,new CareerValues.Transition("SHORTLISTED","Advance review"),1,UUID.randomUUID().toString(),UUID.randomUUID());assertThat(shortlisted.version()).isEqualTo(2);assertThatThrownBy(()->service.transition(manage,created,new CareerValues.Transition("REVIEWED","Repeat review"),2,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(f->((Problem.Failure)f).code).isEqualTo(ProblemCode.INVALID_TRANSITION);}
}
